# "As One" tiene 2 descripciones distintas para la misma habilidad (Glastrier/Spectrier)
AS_ONE_DESCS = {
  "Combines Unnerve and Chilling Neigh Abilities." => "Combina las Habilidades Nerviosismo y Relincho Gélido.",
  "Combines Unnerve and Grim Neigh Abilities." => "Combina las Habilidades Nerviosismo y Relincho Lúgubre.",
}

["Data/messages_es_game.dat", "Data/messages_game.dat"].each do |path|
  data = File.open(path, "rb") { |f| Marshal.load(f) }
  names_hash = data[ABILITY_NAMES]
  descs_hash = data[ABILITY_DESCRIPTIONS]
  matched_n = 0
  matched_d = 0
  PAIRS.each do |eng_name, es_name, eng_desc, es_desc|
    matched_n += 1 if names_hash.key?(eng_name)
    names_hash[eng_name] = es_name
    matched_d += 1 if descs_hash.key?(eng_desc)
    descs_hash[eng_desc] = es_desc
  end
  names_hash["As One"] = "Como Uno Solo"
  AS_ONE_DESCS.each { |k, v| descs_hash[k] = v }
  File.open(path, "wb") { |f| Marshal.dump(data, f) }
  puts "#{path}: nombres coincidentes=#{matched_n}/#{PAIRS.size}, descripciones coincidentes=#{matched_d}/#{PAIRS.size}"
end
